"use client";

import "./accordion.css";

import type React from "react";

import { Accordion as BaseAccordion } from "@base-ui/react/accordion";
import { cn } from "tailwind-variants";

import { AccordionContext, useAccordionContext } from "./accordion.context";
import { accordionVariants, type AccordionVariants } from "./accordion.variants";

export type AccordionProps = AccordionVariants & React.ComponentProps<typeof BaseAccordion.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/accordion/content.md
 */
export const AccordionRoot = ({ children, className, variant, ...props }: AccordionProps) => {
  const slots = accordionVariants({ variant });

  return (
    <AccordionContext.Provider value={{ slots }}>
      <BaseAccordion.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseAccordion.Root>
    </AccordionContext.Provider>
  );
};

export type AccordionItemProps = React.ComponentProps<typeof BaseAccordion.Item>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/accordion/content.md
 */
export const AccordionItem = ({ className, ...props }: AccordionItemProps) => {
  const { slots } = useAccordionContext();
  return <BaseAccordion.Item className={cn(slots.item(), className)} {...props} />;
};

export type AccordionHeaderProps = React.ComponentProps<typeof BaseAccordion.Header>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/accordion/content.md
 */
export const AccordionHeader = ({ className, ...props }: AccordionHeaderProps) => {
  const { slots } = useAccordionContext();
  return <BaseAccordion.Header className={cn(slots.header(), className)} {...props} />;
};

export type AccordionTriggerProps = React.ComponentProps<typeof BaseAccordion.Trigger> & {
  hideChevron?: boolean;
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/accordion/content.md
 */
export const AccordionTrigger = ({
  children,
  className,
  hideChevron = false,
  ...props
}: AccordionTriggerProps) => {
  const { slots } = useAccordionContext();
  return (
    <BaseAccordion.Trigger className={cn(slots.trigger(), className)} {...props}>
      {children}
      {!hideChevron && (
        <svg
          className="h-4 w-4 shrink-0 text-muted-foreground transition-transform duration-200 group-data-panel-open:rotate-180"
          fill="none"
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth="2"
          viewBox="0 0 24 24"
        >
          <path d="m6 9 6 6 6-6" />
        </svg>
      )}
    </BaseAccordion.Trigger>
  );
};

export type AccordionPanelProps = React.ComponentProps<typeof BaseAccordion.Panel>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/accordion/content.md
 */
export const AccordionPanel = ({ children, className, ...props }: AccordionPanelProps) => {
  const { slots } = useAccordionContext();
  return (
    <BaseAccordion.Panel className={cn(slots.panel(), className)} {...props}>
      <div className="px-4 py-3 text-muted-foreground">{children}</div>
    </BaseAccordion.Panel>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const accordionVariants = tv({
  slots: {
    root: "accordion",
    item: "accordion__item",
    header: "accordion__header",
    trigger: "accordion__trigger group",
    panel: "accordion__panel",
  },
  variants: {
    variant: {
      default: {
        root: "accordion--default",
      },
      outline: {
        root: "accordion--outline",
      },
      ghost: {
        root: "accordion--ghost",
      },
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

export type AccordionVariants = VariantProps<typeof accordionVariants>;

"use client";

import { createContext, useContext } from "react";

import { accordionVariants } from "./accordion.variants";

export type AccordionContext = {
  slots: ReturnType<typeof accordionVariants>;
};

export const AccordionContext = createContext<AccordionContext | null>(null);

export const useAccordionContext = () => {
  const context = useContext(AccordionContext);
  return context ?? { slots: accordionVariants() };
};

.accordion {
  @apply flex w-full flex-col border border-border text-foreground rounded-xl overflow-hidden;
}

.accordion--default {
  @apply bg-card border-border shadow-sm;
}

.accordion--outline {
  @apply bg-transparent border-border;
}

.accordion--ghost {
  @apply bg-transparent border-none shadow-none rounded-none;
}

.accordion__item {
  @apply border-b border-border last:border-b-0;
}

.accordion__header {
  @apply m-0 flex;
}

.accordion__trigger {
  @apply flex w-full items-center justify-between gap-4 bg-transparent px-4 py-3 text-left text-sm font-medium text-foreground select-none transition-colors hover:not-data-disabled:bg-accent hover:not-data-disabled:text-accent-foreground focus-visible:relative focus-visible:z-10 focus-visible:outline-2 focus-visible:outline-ring disabled:opacity-50 disabled:cursor-not-allowed;
}

.accordion__panel {
  @apply h-[var(--accordion-panel-height)] overflow-hidden text-sm transition-[height] duration-150 ease-out data-ending-style:h-0 data-starting-style:h-0;
}

import {
  AccordionHeader,
  AccordionItem,
  AccordionPanel,
  AccordionRoot,
  AccordionTrigger,
} from "./accordion";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/accordion/content.md
 */
export const Accordion = {
  Header: AccordionHeader,
  Item: AccordionItem,
  Panel: AccordionPanel,
  Root: AccordionRoot,
  Trigger: AccordionTrigger,
};

export { AccordionHeader, AccordionItem, AccordionPanel, AccordionRoot, AccordionTrigger };

export type {
  AccordionHeaderProps,
  AccordionItemProps,
  AccordionPanelProps,
  AccordionProps,
  AccordionTriggerProps,
} from "./accordion";
export { AccordionContext, useAccordionContext } from "./accordion.context";
export { type AccordionVariants, accordionVariants } from "./accordion.variants";
